      summaryAdultsEnglish: "Verses 18:35-41 show arrogance escalating to denial of the Hereafter: 'I do not think the Hour will occur' (18:36). His companion responded with monotheism and humility: 'But as for me, He is Allah, my Lord, and I associate no partner with my Lord' (18:38). The believing companion taught the protective phrase: 'If only when you entered your garden you had said: What Allah wills' (18:39). [Reference: Tafsir Ibn Kathir — 18:35-41, needs verification]",
